    seq = 'ATGAAATAAGGCTTACATTAGCCCGGGTAA'
    rc = _revcomp(seq)
    fwd = {p for _, _, _, p in find_orfs(seq)}
    rev = {p for _, _, _, p in find_orfs(rc)}
    assert fwd and rev
    assert fwd == rev


